using System.Diagnostics;
using System.Text.Json;
using RiftAssist.ControlCenter.Core;

internal static class PhaseEightProofs
{
    public static async Task RunAsync(ProofSuite s,BackendLayout backend,string temp)
    {
        var deployment=Path.GetFullPath(Path.Combine(backend.Root,"../../deployment"));if(!Directory.Exists(deployment))deployment=Path.GetFullPath(Path.Combine(backend.Root,"../../control-center/deployment"));
        var labs=Path.Combine(temp,"phase8","DeploymentLabs");Directory.CreateDirectory(labs);var root=Path.Combine(labs,Guid.NewGuid().ToString("D"));
        var real=new LocalDeploymentClient(root,backend,deployment,Path.Combine(deployment,"../deployment-manifest.json"),new NativeToolRunner());var co=new DeploymentCoordinator(real);JsonElement package=default,plan=default,deployed=default;
        s.Check("deployment package is code only and ready false with distinct synthetic evidence",()=>{package=DeploymentCatalog.BundledPackage(backend);ProofSuite.True(!package.GetProperty("ready").GetBoolean());ProofSuite.Equal(package.Field("tests").Field("kind").Text(),"synthetic");ProofSuite.True(package.GetProperty("files").EnumerateObject().All(f=>!f.Name.Contains("private",StringComparison.Ordinal)&&!f.Name.Contains("sqlite",StringComparison.Ordinal)));});
        await s.CheckAsync("real local deployment protocol initializes an owned synthetic target",async()=>{var result=await real.CallAsync("init",new{},default);ProofSuite.Equal(result.Field("route").Field("version").Text(),"v0.1.7");ProofSuite.True(!result.GetProperty("productionEnabled").GetBoolean());});
        await s.CheckAsync("production mutation is denied before any client transport even with consent",async()=>{var fake=new Client();var p=ProtocolJson.Element(new{kind="deploy"});await ProofSuite.ThrowsAsync(()=>new DeploymentCoordinator(fake).ExecuteAsync("azure-production",p,AnalysisConsent.Approve("lab-deploy",DeploymentPolicy.Preview(p)),null,default));ProofSuite.Equal(fake.Calls,0);});
        await s.CheckAsync("prepared plan binds package hash source commit and lab identity",async()=>{plan=await real.CallAsync("plan",new{package},default);ProofSuite.Equal(plan.Field("ownerId").Text(),Path.GetFileName(root));ProofSuite.Equal(plan.Field("commit").Text(),package.Field("commit").Text());ProofSuite.Equal(plan.Field("packageDigest").Text(),package.Field("digest").Text());});
        await s.CheckAsync("deployment exact consent cannot be reused for another destination",async()=>await ProofSuite.ThrowsAsync(()=>co.ExecuteAsync(DeploymentPolicy.Target,plan,AnalysisConsent.Approve("wrong",DeploymentPolicy.Preview(plan)),package,default)));
        await s.CheckAsync("bundled Node code and native client execute backup deployment health and routing",async()=>{deployed=await co.ExecuteAsync(DeploymentPolicy.Target,plan,AnalysisConsent.Approve("lab-deploy",DeploymentPolicy.Preview(plan)),package,default);ProofSuite.Equal(deployed.Field("state").Text(),"completed");var status=await real.CallAsync("status",new{},default);ProofSuite.Equal(status.Field("route").Field("version").Text(),"v0.2.0");});
        await s.CheckAsync("native client can validate encrypted backup without receiving rows or keys",async()=>{var result=await real.CallAsync("verify-backup",new{backupId=deployed.Field("backupId").Text()},default);ProofSuite.True(result.GetProperty("verified").GetBoolean());ProofSuite.True(!result.GetRawText().Contains("recordKey",StringComparison.Ordinal));});
        await s.CheckAsync("approved rollback uses separate plan and changes routing without database restore",async()=>{var p=await real.CallAsync("rollback-plan",new{operationId=deployed.Field("id").Text()},default);var result=await co.ExecuteAsync(DeploymentPolicy.Target,p,AnalysisConsent.Approve("lab-rollback",DeploymentPolicy.Preview(p)),null,default);ProofSuite.Equal(result.Field("state").Text(),"rolled-back");});
        await s.CheckAsync("deployment requery is read-only and cannot replay completed writes",async()=>{var before=await real.CallAsync("status",new{},default);var after=await real.CallAsync("reconcile",new{},default);ProofSuite.Equal(before.GetRawText(),after.GetRawText());});
        await s.CheckAsync("GitHub catalog validates workflow evidence for exact selected commit",async()=>{var runner=new PhaseSevenProofs.Runner(q=>{if(q.Arguments.Last().Contains("commits?",StringComparison.Ordinal))return new(0,JsonSerializer.Serialize(new[]{new{sha=new string('a',40),commit=new{message="synthetic source"}}}));return new(0,JsonSerializer.Serialize(new{workflow_runs=new[]{new{head_sha=new string('a',40),head_branch=RepairScope.BaseBranch,conclusion="success",path=".github/workflows/control-center.yml",id=1},new{head_sha=new string('a',40),head_branch=RepairScope.BaseBranch,conclusion="success",path=".github/workflows/rules-tests.yml",id=2}}}));});var result=await new DeploymentCatalog("fake-gh.exe",temp,runner).ListAsync(default);ProofSuite.True(result.Single().TestsPassed);ProofSuite.True(runner.Calls.All(q=>!q.Arguments.Contains("POST")&&q.Input is null));});
        await s.CheckAsync("missing or stale CI evidence prevents deployment package selection",async()=>{var r=new PhaseSevenProofs.Runner(q=>new(0,q.Arguments.Last().Contains("commits?",StringComparison.Ordinal)?JsonSerializer.Serialize(new[]{new{sha=new string('a',40),commit=new{message="synthetic"}}}):"{\"workflow_runs\":[]}"));var catalog=new DeploymentCatalog("fake-gh.exe",temp,r);var rows=await catalog.ListAsync(default);ProofSuite.True(!rows.Single().TestsPassed);await ProofSuite.ThrowsAsync(()=>catalog.PackageAsync(rows.Single(),default));});
        if(OperatingSystem.IsWindows()){
            s.Check("Windows process ownership uses DPAPI and leaves no leases after normal child exit",()=>{var own=WindowsOwnedProcess.Inspect();ProofSuite.True(own.All(o=>o.State.StartsWith("active-owner",StringComparison.Ordinal)));});
            await s.CheckAsync("forced owner crash kills owned Node process tree; orphan receipt requery never uses PID termination",async()=>{
                var guard=Path.Combine(temp,"phase8-guard");Directory.CreateDirectory(guard);var ready=Path.Combine(guard,"ready.json");var receipts=Path.Combine(guard,"receipts");
                var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true};foreach(var arg in new[]{"--owned-parent-fixture",backend.Node,guard,ready,receipts})start.ArgumentList.Add(arg);
                using var parent=Process.Start(start)!;try{var until=DateTime.UtcNow.AddSeconds(12);while((!File.Exists(ready)||!Directory.Exists(receipts)||!Directory.EnumerateFiles(receipts,"*.dpapi").Any())&&DateTime.UtcNow<until&&!parent.HasExited)await Task.Delay(100);ProofSuite.True(File.Exists(ready));using var d=JsonDocument.Parse(File.ReadAllBytes(ready));var pid=d.RootElement.GetProperty("pid").GetInt32();var child=d.RootElement.GetProperty("child").GetInt32();parent.Kill();await parent.WaitForExitAsync();
                    until=DateTime.UtcNow.AddSeconds(5);bool alive;do{try{using var p=Process.GetProcessById(pid);alive=!p.HasExited;}catch(ArgumentException){alive=false;}if(alive)await Task.Delay(100);}while(alive&&DateTime.UtcNow<until);ProofSuite.True(!alive);try{using var descendant=Process.GetProcessById(child);using var exited=new CancellationTokenSource(TimeSpan.FromSeconds(5));await descendant.WaitForExitAsync(exited.Token);ProofSuite.True(descendant.HasExited);}catch(ArgumentException){}
                    ProofSuite.True(WindowsOwnedProcess.Inspect(false,receipts).Count==1);WindowsOwnedProcess.Inspect(true,receipts);ProofSuite.True(!Directory.EnumerateFiles(receipts,"*.dpapi").Any());
                }finally{if(!parent.HasExited)parent.Kill(true);}
            });
        }
    }
    public static async Task<int> OwnedParentFixture(string[] args)
    {await new NativeToolRunner(args[4]).RunAsync(new(args[1],["-e","process.stdin.resume();process.stdin.on('end',()=>{const c=require('node:child_process').spawn(process.execPath,['-e','setInterval(()=>{},1000)'],{stdio:'ignore'});require('node:fs').writeFileSync(process.argv[1],JSON.stringify({pid:process.pid,child:c.pid}));setInterval(()=>{},1000)});",args[3]],args[2],Seconds:60),default);return 0;}
    private sealed class Client:IDeploymentClient{public int Calls;public Task<JsonElement> CallAsync(string m,object p,CancellationToken c,Action<string>? progress=null){Calls++;return Task.FromResult(ProtocolJson.Element(new{}));}}
}
